/*
 * Analyze competitor landscape
 * Calculates market insights and summarizes competitive landscape
 */

const competitors = $json.competitors || [];
const targetCompany = $('📝 Input: Target Company').first().json.company_name;

// Calculate market insights
const totalValuation = competitors.reduce((sum, c) => sum + (c.valuation || 0), 0);
const avgEmployees = competitors.length > 0 
  ? Math.round(competitors.reduce((sum, c) => sum + (c.employeesCount || 0), 0) / competitors.length) 
  : 0;
const avgValuation = competitors.length > 0 
  ? Math.round(totalValuation / competitors.length) 
  : 0;

// Categorize by size
const small = competitors.filter(c => (c.employeesCount || 0) < 50).length;
const medium = competitors.filter(c => (c.employeesCount || 0) >= 50 && (c.employeesCount || 0) < 200).length;
const large = competitors.filter(c => (c.employeesCount || 0) >= 200).length;

return {
  target_company: targetCompany,
  target_domain: $('📝 Input: Target Company').first().json.company_domain,
  competitor_count: competitors.length,
  competitors: competitors.map(c => ({
    name: c.name,
    description: c.shortDescription,
    founded: c.founded_year,
    employees: c.employeesCount,
    valuation: c.valuation,
    hq: c.hq,
    company_type: c.companyType,
    funding: c.funding_metrics ? {
      total: c.funding_metrics.total,
      latest_round: c.funding_metrics.latest,
      currency: c.funding_metrics.currency_code
    } : null,
    twitter_followers: c.twitter_followers,
    growth_score: c.growth
  })),
  market_insights: {
    total_market_valuation: totalValuation,
    avg_employees: avgEmployees,
    avg_valuation: avgValuation,
    company_size_breakdown: {
      small_under_50: small,
      medium_50_200: medium,
      large_200_plus: large
    }
  },
  meta: {
    analyzed_at: new Date().toISOString(),
    credits_used: null
  }
};
